&reftitle.description;
voiddebug_print_backtrace intoptions0 intlimit0
debug_print_backtrace prints a PHP backtrace. It prints the function calls, included/required files and evaled stuff.

    &reftitle.examples;

     debug_print_backtrace example


<?php
// include.php file

function a() {
    b();
}

function b() {
    c();
}

function c(){
    debug_print_backtrace();
}

a();

?>




<?php
// test.php file
// this is the file you should run

include 'include.php';
?>


     &example.outputs.similar;


#0 /tmp/include.php(9): c()
#1 /tmp/include.php(5): b()
#2 /tmp/include.php(16): a()
#3 /tmp/test.php(5): include('/tmp/include.ph...')
